
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_dldf_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_dldf", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.282820640991373e+00, -1.277582736558751e+00, -1.269485897498429e+00, -1.256681035509417e+00, -1.235907029533492e+00, -1.201395625331207e+00, -1.143480919294000e+00, -1.049355796727839e+00, -9.157899057881863e-01, -7.747888129300516e-01, -5.979138108465555e-01, -3.125387084941157e-01, -2.305683255551642e-01, -1.987073152482955e-01, -1.663150584701406e-01, -1.445771100144460e-01, -1.332846649909148e-01, -7.880730623256811e-02, -1.914595469240415e-02, -2.166101389285449e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


